  @protected
  void sse_encode_message_event(MessageEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case MessageEvent_Snapshot(message: final message):
        sse_encode_i_32(0, serializer);
        sse_encode_box_autoadd_message_dto(message, serializer);
      case MessageEvent_ContentDelta(delta: final delta):
        sse_encode_i_32(1, serializer);
        sse_encode_box_autoadd_content_delta_dto(delta, serializer);
      case MessageEvent_ToolCallStarted(toolCall: final toolCall):
        sse_encode_i_32(2, serializer);
        sse_encode_box_autoadd_tool_call_summary_dto(toolCall, serializer);
      case MessageEvent_ToolCallFinished(toolCall: final toolCall):
        sse_encode_i_32(3, serializer);
        sse_encode_box_autoadd_tool_call_finished_dto(toolCall, serializer);
      case MessageEvent_Done(message: final message):
        sse_encode_i_32(4, serializer);
        sse_encode_box_autoadd_message_dto(message, serializer);
      case MessageEvent_Error(error: final error):
        sse_encode_i_32(5, serializer);
        sse_encode_box_autoadd_client_error(error, serializer);
    }
  }

